let kakaoPostcodeLoader:Promise<void>|null=null;
function loadKakaoPostcode(){if((window as any).daum?.Postcode)return Promise.resolve();if(kakaoPostcodeLoader)return kakaoPostcodeLoader;kakaoPostcodeLoader=new Promise<void>((resolve,reject)=>{const script=document.createElement("script");script.src="https://t1.daumcdn.net/mapjsapi/bundle/postcode/prod/postcode.v2.js";script.onload=()=>resolve();script.onerror=()=>reject(new Error("카카오 주소 검색을 불러오지 못했습니다."));document.head.append(script)});return kakaoPostcodeLoader}
function openAgreementDetail(kind:"terms"|"privacy"){const termsText="Paxlink는 성당 공동체의 신도 정보 확인과 서비스 제공을 위한 플랫폼입니다. 회원은 정확한 정보를 제공하고 타인의 정보를 도용하지 않아야 합니다. 서비스 운영을 방해하거나 불법적인 목적으로 이용할 수 없으며, 회원은 언제든지 탈퇴를 요청할 수 있습니다.",privacyText="수집 항목: 소속 성당, 이름, 세례명, 이메일, 생년월일, 전화번호, 모바일폰번호, 주소, 우편번호. 이용 목적: 신도 식별, 성당 공동체 서비스 및 공지 제공, 문의 응대. 보유 기간: 회원 탈퇴 또는 관련 법령에 따른 보관 기간까지. 동의를 거부할 수 있으나 회원가입이 제한됩니다.";modal(kind==="terms"?"이용약관":"개인정보 수집·이용 동의",`<p style="text-align:left;line-height:1.8;white-space:pre-wrap">${kind==="terms"?termsText:privacyText}</p>`)}
function enhanceMemberProfileForm(form:HTMLFormElement){const postal=form.elements.namedItem("postalCode") as HTMLInputElement,address=form.elements.namedItem("address") as HTMLInputElement,addressDetail=form.elements.namedItem("addressDetail") as HTMLInputElement,postalLabel=postal.closest("label")!;const addressButton=document.createElement("button");addressButton.className="green-outline member-profile-address-search";addressButton.type="button";addressButton.textContent="카카오 주소 검색";postalLabel.insertAdjacentElement("afterend",addressButton);addressButton.onclick=async()=>{addressButton.disabled=true;try{await loadKakaoPostcode();new (window as any).daum.Postcode({oncomplete:(data:{zonecode:string;roadAddress:string;jibunAddress:string})=>{postal.value=data.zonecode;address.value=data.roadAddress||data.jibunAddress;addressDetail.focus()}}).open()}catch(error){form.querySelector<HTMLElement>(".member-profile-error")!.textContent=(error as Error).message}finally{addressButton.disabled=false}};form.querySelectorAll<HTMLElement>(".profile-consent.confirmed").forEach((label,index)=>{const button=document.createElement("button");button.type="button";button.className="agreement-detail-button";button.textContent="내용 확인";button.onclick=()=>openAgreementDetail(index===0?"terms":"privacy");label.append(button)})}
