type ParishionerNotification={id:number;category:string;title:string;message:string;readAt:string|null;createdAt:string;unread:boolean};
let notificationTimer=0,notificationInitialized=false,latestNotificationId=0,notificationItems:ParishionerNotification[]=[];
function openNotificationCenter(){document.querySelector(".member-notification-modal")?.remove();const layer=document.createElement("div");layer.className="member-modal member-notification-modal";layer.innerHTML=`<section class="member-modal-box"><h3>알림</h3><div class="member-modal-body">${notificationItems.length?notificationItems.map(item=>`<article class="member-notification-item ${item.unread?"unread":""}"><div><strong>${escapeHtml(item.title)}</strong>${item.unread?'<b>읽지 않음</b>':'<b class="read">읽음</b>'}</div><p>${escapeHtml(item.message)}</p><footer><time>${new Date(item.createdAt).toLocaleString("ko-KR")}</time>${item.unread?`<button class="member-notification-read" data-notification-read="${item.id}" type="button">읽음</button>`:""}</footer></article>`).join(""):'<p class="member-notification-empty">도착한 알림이 없습니다.</p>'}</div><footer><button class="green-outline" type="button">닫기</button></footer></section>`;document.body.append(layer);layer.querySelector(":scope>.member-modal-box>footer button")!.addEventListener("click",()=>layer.remove());layer.querySelectorAll<HTMLButtonElement>("[data-notification-read]").forEach(button=>button.onclick=async()=>{button.disabled=true;const response=await fetch(`/api/parishioner/notifications/${button.dataset.notificationRead}/read`,{method:"POST"});if(!response.ok){button.disabled=false;return}location.reload()})}
function showRealtimeNotification(item:ParishionerNotification){document.querySelector(".member-realtime-toast")?.remove();const toast=document.createElement("button");toast.className="member-realtime-toast";toast.type="button";toast.innerHTML=`<span>새 알림</span><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.message)}</p>`;document.body.append(toast);toast.onclick=()=>{toast.remove();openNotificationCenter()};window.setTimeout(()=>toast.remove(),8000)}
async function pollNotifications(announce=true){try{const response=await fetch("/api/parishioner/notifications"),items=await response.json() as ParishionerNotification[];if(!response.ok)return;const newest=items[0]?.id??0;if(notificationInitialized&&announce&&newest>latestNotificationId){const arrived=items.find(item=>item.id>latestNotificationId);if(arrived)showRealtimeNotification(arrived)}notificationItems=items;latestNotificationId=Math.max(latestNotificationId,newest);notificationInitialized=true;const unread=items.filter(item=>item.unread).length,badge=document.querySelector<HTMLElement>("#member-notification-button b")!;badge.textContent=String(unread);badge.hidden=!unread}catch(error){console.error(error)}}
function mountRealtimeNotifications(){document.querySelector("#member-notification-button")?.addEventListener("click",openNotificationCenter);window.clearInterval(notificationTimer);void pollNotifications(false);notificationTimer=window.setInterval(()=>void pollNotifications(),3000)}
async function getNotices(url:string){const response=await fetch(url),data=await response.json() as ParishNotice[]&{message?:string};if(!response.ok)throw new Error(data.message??"공지사항을 불러오지 못했습니다.");return data}
let memberNotices:ParishNotice[]=[],visibleMemberNoticeCount=2;
function openMemberNoticeDetail(item:ParishNotice){document.querySelector(".member-notice-detail-modal")?.remove();const layer=document.createElement("div");layer.className="member-modal member-notice-detail-modal";layer.innerHTML=`<section class="member-modal-box"><h3>${escapeHtml(item.title)}</h3><div class="member-modal-body"><div class="member-notice-detail-meta">${item.pinned?'<b>상단 고정</b>':""}<time>${new Date(item.createdAt).toLocaleDateString("ko-KR")}</time></div><p>${escapeHtml(item.content)}</p>${item.attachments.length?`<div class="popup-files">${item.attachments.map(file=>`<a href="/api/parishioner/notices/${item.id}/attachments/${file.slot}">📎 ${escapeHtml(file.name)}</a>`).join("")}</div>`:""}</div><footer><button class="green-outline" type="button">닫기</button></footer></section>`;document.body.append(layer);layer.querySelector<HTMLButtonElement>("footer button")!.onclick=()=>layer.remove()}
function renderMemberNotices(){const list=document.querySelector<HTMLElement>("#member-notice-list"),empty=document.querySelector<HTMLElement>("#member-notice-empty"),more=document.querySelector<HTMLButtonElement>(".member-notice-more");if(!list||!empty||!more)return;list.innerHTML=memberNotices.slice(0,visibleMemberNoticeCount).map(item=>`<article class="member-notice"><div>${item.pinned?'<b>상단 고정</b>':""}<time>${new Date(item.createdAt).toLocaleDateString("ko-KR")}</time></div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.content)}</p><button class="member-notice-detail green-outline" data-member-notice-detail="${item.id}" type="button">상세보기</button></article>`).join("");list.querySelectorAll<HTMLButtonElement>("[data-member-notice-detail]").forEach(button=>button.onclick=()=>{const item=memberNotices.find(notice=>notice.id===Number(button.dataset.memberNoticeDetail));if(item)openMemberNoticeDetail(item)});more.hidden=visibleMemberNoticeCount>=memberNotices.length;empty.hidden=memberNotices.length>0}
async function loadNotices(){try{memberNotices=await getNotices("/api/parishioner/notices");visibleMemberNoticeCount=2;const header=document.querySelector<HTMLElement>(".member-notices>header")!;if(!header.querySelector(".member-notice-more")){const button=document.createElement("button");button.className="member-notice-more green-outline";button.type="button";button.textContent="more";button.onclick=()=>{visibleMemberNoticeCount+=2;renderMemberNotices()};header.append(button)}document.querySelector("#member-notice-count")!.textContent=`총 ${memberNotices.length}개`;renderMemberNotices();await showNoticePopup()}catch(error){console.error(error)}}
async function showNoticePopup(){const notices=await getNotices("/api/parishioner/notices/popups/active"),today=new Date().toLocaleDateString("en-CA"),item=notices.find(value=>localStorage.getItem(`paxlink.parishioner.notice.${value.id}`)!==today);if(!item)return;const layer=document.createElement("div");layer.className="member-modal member-notice-popup";layer.innerHTML=`<section class="member-modal-box"><h3>${escapeHtml(item.title)}</h3><div class="member-modal-body"><p>${escapeHtml(item.content)}</p>${item.attachments.length?`<div class="popup-files">${item.attachments.map(file=>`<a href="/api/parishioner/notices/${item.id}/attachments/${file.slot}">📎 ${escapeHtml(file.name)}</a>`).join("")}</div>`:""}</div><label class="popup-today"><input type="checkbox"> 오늘 하루 보지 않기</label><button class="green-button" type="button">확인</button></section>`;document.body.append(layer);layer.querySelector("button")!.addEventListener("click",()=>{if(layer.querySelector<HTMLInputElement>("input")!.checked)localStorage.setItem(`paxlink.parishioner.notice.${item.id}`,today);layer.remove()})}
