async function loadMemberGroups(){const response=await fetch("/api/parishioner/groups"),groups=await response.json() as ParishGroup[]&{message?:string};if(!response.ok)throw new Error(groups.message);document.querySelector("#member-group-list")!.innerHTML=groups.map(group=>`<article class="member-group-card">${group.hasIcon?`<img src="/api/parishioner/groups/${group.id}/icon" alt="">`:'<span class="member-group-icon">♙</span>'}<div><b class="group-state ${group.status}">${memberGroupStatus[group.status]}</b><h3>${escapeHtml(group.nameKo)}</h3><small>${escapeHtml(group.nameEn??"")}</small><p>${escapeHtml(group.description??"설명이 없습니다.")}</p><em>${escapeHtml(group.regularMeeting??"정기미팅 미정")} · 운영자 ${escapeHtml(group.operatorName)}</em></div></article>`).join("");const created=groups.filter(group=>group.isOperator).length,joined=groups.filter(group=>!group.isOperator&&group.membershipStatus==="approved").length;document.querySelector("#member-group-count")!.textContent=`총 ${groups.length}개 (운영: ${created} / 가입: ${joined})`;document.querySelector<HTMLElement>("#member-group-empty")!.hidden=groups.length>0}
function openMemberGroupForm(){const layer=document.createElement("div");layer.className="member-modal member-group-modal";layer.innerHTML=`<section class="member-modal-box"><h3>단체 생성 신청</h3><form><label>아이콘 이미지<input id="member-group-icon" type="file" accept="image/*"></label><label>단체명(국문) *<input id="member-group-ko" maxlength="200" required></label><label>단체명(영문)<input id="member-group-en" maxlength="300"></label><label>정기미팅<input id="member-group-meeting" maxlength="500"></label><label>모임설명<textarea id="member-group-description" rows="5"></textarea></label><p></p><div><button class="green-outline" type="button">취소</button><button class="green-button" type="submit">승인 신청</button></div></form></section>`;document.body.append(layer);layer.querySelector<HTMLButtonElement>('button[type="button"]')!.onclick=()=>layer.remove();layer.querySelector("form")!.onsubmit=async event=>{event.preventDefault();const error=layer.querySelector("form>p")!;try{const file=layer.querySelector<HTMLInputElement>("#member-group-icon")!.files?.[0];if(file&&file.size>2*1024*1024)throw new Error("아이콘 이미지는 2MB까지 업로드할 수 있습니다.");const icon=file?await new Promise<{iconType:string;iconData:string}>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({iconType:file.type,iconData:String(reader.result).split(",")[1]??""});reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file)}):{iconType:"",iconData:""},payload={...icon,nameKo:layer.querySelector<HTMLInputElement>("#member-group-ko")!.value,nameEn:layer.querySelector<HTMLInputElement>("#member-group-en")!.value,regularMeeting:layer.querySelector<HTMLInputElement>("#member-group-meeting")!.value,description:layer.querySelector<HTMLTextAreaElement>("#member-group-description")!.value},save=await fetch("/api/parishioner/groups",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)}),result=await save.json();if(!save.ok)throw new Error(result.errors?Object.values(result.errors)[0]:result.message);layer.remove();await loadMemberGroups();modal("단체 생성",`<p>${escapeHtml(result.message)}</p>`)}catch(reason){error.textContent=(reason as Error).message}}}
function mountMemberGroups(){const home=document.querySelector(".member-home");if(!home||document.querySelector(".member-groups"))return;home.querySelector(".member-notices")?.insertAdjacentHTML("beforebegin",`<section class="member-groups"><header><div><h2>단체</h2><span id="member-group-count"></span></div><button id="member-group-create" class="green-button" type="button">+ 단체 생성</button></header><div id="member-group-list" class="member-group-list"></div><p id="member-group-empty" hidden>등록된 단체가 없습니다.</p></section>`);document.querySelector("#member-group-create")!.addEventListener("click",openMemberGroupForm);void loadMemberGroups()}
new MutationObserver(mountMemberGroups).observe(document.body,{childList:true,subtree:true});
function mountMembershipResults(){const groups=document.querySelector(".member-groups");if(!groups||groups.getAttribute("data-membership-results-mounted"))return;groups.setAttribute("data-membership-results-mounted","true");void loadMembershipResults()}
new MutationObserver(mountMembershipResults).observe(document.body,{childList:true,subtree:true});
async function loadMembershipResults(){try{const response=await fetch("/api/parishioner/group-membership-results"),results=await response.json() as MembershipResult[]&{message?:string};if(!response.ok)throw new Error(results.message);const unread=results.find(item=>item.unread);if(unread&&!document.querySelector(".membership-result-modal"))showMembershipResult(unread)}catch(error){console.error(error)}}
function showMembershipResult(item:MembershipResult){const layer=document.createElement("div");layer.className="member-modal membership-result-modal";layer.innerHTML=`<section class="member-modal-box"><h3>단체 가입 결과</h3><div class="member-modal-body"><strong>${escapeHtml(item.groupName)}</strong><b class="result-${item.status}">${item.status==="approved"?"가입이 승인되었습니다.":"가입이 반려되었습니다."}</b>${item.status==="rejected"?`<dl><dt>반려 사유</dt><dd>${escapeHtml(item.rejectionReason??"-")}</dd></dl>`:""}</div><button class="green-button" type="button">확인</button></section>`;document.body.append(layer);layer.querySelector("button")!.onclick=async()=>{await fetch(`/api/parishioner/group-membership-results/${item.id}/read`,{method:"POST"});layer.remove();await loadMembershipResults()}}
let decoratingMemberGroups=false;
new MutationObserver(async()=>{const list=document.querySelector("#member-group-list");if(!list||!list.children.length||list.querySelector(".member-group-join")||decoratingMemberGroups)return;decoratingMemberGroups=true;try{const response=await fetch("/api/parishioner/groups"),groups=await response.json() as ParishGroup[];[...list.querySelectorAll<HTMLElement>(".member-group-card")].forEach((card,index)=>{const group=groups[index]!,actions=document.createElement("div");actions.className="member-group-actions";const action=document.createElement("button");action.type="button";action.className="member-group-join";action.textContent=group.isOperator?"내가 만든 단체":group.membershipStatus==="approved"?"탈퇴 요청":group.membershipStatus==="withdrawal_requested"?"탈퇴 승인 대기":group.membershipStatus==="requested"?"가입 신청 중":"가입 신청";action.disabled=group.isOperator||group.membershipStatus==="requested"||group.membershipStatus==="withdrawal_requested"||group.status!=="approved";action.onclick=()=>group.membershipStatus==="approved"?requestGroupWithdrawal(group):joinGroup(group.id,group.nameKo);actions.append(action);if(group.isOperator){const manage=document.createElement("button");manage.type="button";manage.className="member-group-withdrawals";manage.textContent=`탈퇴 요청 ${group.withdrawalCount}명`;manage.onclick=()=>openGroupWithdrawals(group);actions.append(manage)}card.querySelector("div")!.append(actions)})}finally{decoratingMemberGroups=false}}).observe(document.body,{childList:true,subtree:true});
function requestGroupJoinMessage(groupName:string){return new Promise<string|null>(resolve=>{const layer=document.createElement("div");layer.className="member-modal group-join-message-modal";layer.innerHTML=`<section class="member-modal-box"><h3>단체 가입 신청</h3><form><strong>${escapeHtml(groupName)}</strong><label>등록자에게 전달할 메시지<textarea maxlength="2000" rows="7" placeholder="가입 동기나 등록자에게 전달할 내용을 작성해 주세요."></textarea></label><p></p><footer><button class="green-outline" type="button">취소</button><button class="green-button" type="submit" disabled>가입 신청</button></footer></form></section>`;document.body.append(layer);const textarea=layer.querySelector<HTMLTextAreaElement>("textarea")!,submit=layer.querySelector<HTMLButtonElement>('button[type="submit"]')!;textarea.oninput=()=>submit.disabled=!textarea.value.trim();layer.querySelector<HTMLButtonElement>('button[type="button"]')!.onclick=()=>{layer.remove();resolve(null)};layer.querySelector<HTMLFormElement>("form")!.onsubmit=event=>{event.preventDefault();const message=textarea.value.trim();if(!message)return;layer.remove();resolve(message)};textarea.focus()})}
async function joinGroup(id:number,name:string){const message=await requestGroupJoinMessage(name);if(message===null)return;try{const response=await fetch(`/api/parishioner/groups/${id}/join`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message})}),result=await response.json();if(!response.ok)throw new Error(result.message);await loadMemberGroups();modal("단체 가입",`<p>${escapeHtml(result.message)}</p>`)}catch(error){modal("단체 가입",`<p>${escapeHtml((error as Error).message)}</p>`)}}
function confirmGroupWithdrawal(name:string){return new Promise<string|null>(resolve=>{const layer=document.createElement("div");layer.className="member-modal group-withdraw-confirm";layer.innerHTML=`<section class="member-modal-box"><h3>단체 탈퇴 요청</h3><form><strong>${escapeHtml(name)}</strong><label>탈퇴 요청 사유<textarea maxlength="2000" rows="6" placeholder="단체 등록자가 확인할 탈퇴 사유를 작성해 주세요."></textarea></label><footer><button class="green-outline" type="button">취소</button><button class="green-button" type="submit" disabled>탈퇴 요청</button></footer></form></section>`;document.body.append(layer);const textarea=layer.querySelector<HTMLTextAreaElement>("textarea")!,submit=layer.querySelector<HTMLButtonElement>('button[type="submit"]')!,done=(value:string|null)=>{layer.remove();resolve(value)};textarea.oninput=()=>submit.disabled=!textarea.value.trim();layer.querySelector<HTMLButtonElement>('button[type="button"]')!.onclick=()=>done(null);layer.querySelector<HTMLFormElement>("form")!.onsubmit=event=>{event.preventDefault();const reason=textarea.value.trim();if(!reason)return;done(reason)};textarea.focus()})}
async function requestGroupWithdrawal(group:ParishGroup){const reason=await confirmGroupWithdrawal(group.nameKo);if(reason===null)return;try{const response=await fetch(`/api/parishioner/groups/${group.id}/withdraw`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({reason})}),result=await response.json();if(!response.ok)throw new Error(result.message);await loadMemberGroups();modal("단체 탈퇴 요청",`<p>${escapeHtml(result.message)}</p>`)}catch(error){modal("단체 탈퇴 요청",`<p>${escapeHtml((error as Error).message)}</p>`)}}
