new MutationObserver(()=>{const input=document.querySelector<HTMLInputElement>("#member-group-meeting");if(!input||input.dataset.scheduleReady)return;input.dataset.scheduleReady="true";input.hidden=true;input.closest("label")!.classList.add("meeting-field");input.insertAdjacentHTML("afterend",`<div class="meeting-schedule">${groupMeetingDays.map(day=>`<div data-member-meeting="${day.key}"><label><input type="checkbox"> ${day.label}요일</label><input class="meeting-from" type="time" disabled><span>~</span><input class="meeting-to" type="time" disabled></div>`).join("")}</div>`);const root=input.closest("label")!;root.querySelectorAll<HTMLElement>("[data-member-meeting]").forEach(row=>{const check=row.querySelector<HTMLInputElement>('input[type="checkbox"]')!;check.onchange=()=>row.querySelectorAll<HTMLInputElement>('input[type="time"]').forEach(time=>{time.disabled=!check.checked;if(!check.checked)time.value=""})});input.closest("form")!.addEventListener("submit",()=>{input.value=JSON.stringify([...root.querySelectorAll<HTMLElement>("[data-member-meeting]")].filter(row=>row.querySelector<HTMLInputElement>('input[type="checkbox"]')!.checked).map(row=>({day:row.dataset.memberMeeting,from:row.querySelector<HTMLInputElement>(".meeting-from")!.value,to:row.querySelector<HTMLInputElement>(".meeting-to")!.value})))},{capture:true})}).observe(document.body,{childList:true,subtree:true});
function mountMemberSharing(){const home=document.querySelector(".member-home"),notices=document.querySelector(".member-notices");if(!home||!notices||document.querySelector(".member-sharing"))return;notices.insertAdjacentHTML("beforebegin",`<section class="member-sharing"><header><div><h2>나눔</h2><p>본당 공동체와 함께하는 나눔 공간입니다.</p></div></header><nav class="member-sharing-tabs" role="tablist" aria-label="나눔 메뉴"><button class="active" data-member-sharing="catacomb" type="button" role="tab" aria-selected="true">카타콤</button><button data-member-sharing="talent" type="button" role="tab" aria-selected="false">달란트</button><button data-member-sharing="prayer-dream" type="button" role="tab" aria-selected="false">기도드림</button></nav><div class="member-sharing-panel" data-member-sharing-panel="catacomb"><span>♡</span><div><h3>카타콤</h3><p>카타콤 나눔 활동을 확인하고 참여할 수 있습니다.</p></div></div><div class="member-sharing-panel" data-member-sharing-panel="talent" hidden><span>◇</span><div><h3>달란트</h3><p>서로의 재능을 나누는 달란트 활동을 확인할 수 있습니다.</p></div></div><div class="member-sharing-panel" data-member-sharing-panel="prayer-dream" hidden><span>†</span><div><h3>기도드림</h3><p>기도를 나누고 함께 마음을 모을 수 있습니다.</p></div></div></section>`);document.querySelectorAll<HTMLButtonElement>("[data-member-sharing]").forEach(button=>button.addEventListener("click",()=>{document.querySelectorAll<HTMLButtonElement>("[data-member-sharing]").forEach(tab=>{const active=tab===button;tab.classList.toggle("active",active);tab.setAttribute("aria-selected",String(active))});document.querySelectorAll<HTMLElement>("[data-member-sharing-panel]").forEach(panel=>panel.hidden=panel.dataset.memberSharingPanel!==button.dataset.memberSharing)}))}
