async function loadMyMissions(){try{const items=await catacombApi<SharingMission[]>("/api/parishioner/missions/mine"),list=document.querySelector("#member-mission-list")!;list.innerHTML=items.map(item=>`<article class="member-mission-card"><header><b class="mission-state ${item.status}">${missionStatusLabels[item.status!]}</b><time>${new Date(item.createdAt).toLocaleString("ko-KR")}</time></header><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.content)}</p><small class="mission-period-label">모집기간 ${item.applicationFrom??"-"} ~ ${item.applicationTo??"-"}</small>${item.tags.length?`<div class="catacomb-tags">${item.tags.map(tag=>`<span>#${escapeHtml(tag)}</span>`).join("")}</div>`:""}<button class="member-mission-applicants" data-owner-applicants="${item.id}" data-title="${escapeHtml(item.title)}" type="button">승인/반려/지원 : ${item.approvedApplicationCount??0} / ${item.rejectedApplicationCount??0} / ${item.applicationCount??0}</button>${item.status==="rejected"?`<div class="member-mission-reason"><strong>반려 사유</strong><p>${escapeHtml(item.rejectionReason??"-")}</p></div>`:""}</article>`).join("");document.querySelector("#member-mission-count")!.textContent=`총 ${items.length}개`;list.querySelectorAll<HTMLButtonElement>("[data-owner-applicants]").forEach(button=>button.onclick=()=>openOwnerApplicants(Number(button.dataset.ownerApplicants),button.dataset.title??"미션"));const rejected=items.find(item=>item.status==="rejected"&&item.decidedAt&&localStorage.getItem(`paxlink.mission.rejected.${item.id}`)!==item.decidedAt);if(rejected){localStorage.setItem(`paxlink.mission.rejected.${rejected.id}`,String(rejected.decidedAt));modal("미션 승인 결과",`<strong>${escapeHtml(rejected.title)}</strong><p>미션이 반려되었습니다.</p><dl><dt>반려 사유</dt><dd>${escapeHtml(rejected.rejectionReason??"-")}</dd></dl>`)}}catch(error){console.error(error)}}
async function loadTalentMissions(){try{const items=await catacombApi<SharingMission[]>("/api/parishioner/talent/missions"),list=document.querySelector("#talent-mission-list")!;list.innerHTML=items.map(item=>{const total=item.applicationCount??0,pending=item.requestedApplicationCount??0,approved=item.approvedApplicationCount??0,summary=`${item.applicationOpen?"모집중":"모집종료"} · 승인 ${approved}명 · 지원자 ${pending}명`,applicants=item.isOwner&&total>0?`<button class="talent-applicant-count" data-talent-applicants="${item.id}" data-title="${escapeHtml(item.title)}" type="button">${summary}</button>`:`<b>${summary}</b>`;return `<article class="talent-mission-card ${item.applicationOpen?"":"is-closed"}"><header><div><strong>${escapeHtml(item.authorName??"익명")}</strong><time>${new Date(item.createdAt).toLocaleDateString("ko-KR")}</time></div>${applicants}</header><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.content)}</p><small class="mission-period-label">모집기간 ${item.applicationFrom??"-"} ~ ${item.applicationTo??"-"}</small>${item.tags.length?`<div class="catacomb-tags">${item.tags.map(tag=>`<span>#${escapeHtml(tag)}</span>`).join("")}</div>`:""}${item.applicationStatus==="rejected"?`<div class="application-rejection-result"><strong>지원 반려 사유</strong><p>${escapeHtml(item.applicationRejectionReason??"반려 사유가 저장되지 않은 이전 처리 건입니다.")}</p></div>`:""}${item.isOwner?'<button class="owner-disabled" type="button" disabled>내가 등록한 미션</button>':item.applicationStatus==="requested"?`<button class="mission-application-cancel" data-mission-cancel="${item.id}" data-mission-apply="${item.id}" type="button">지원 취소</button>`:`<button class="${item.applicationStatus&&item.applicationStatus!=="rejected"?"applied":""}" data-mission-apply="${item.id}" type="button" ${(item.applicationStatus&&item.applicationStatus!=="rejected")||!item.applicationOpen?"disabled":""}>${item.applicationStatus==="approved"?"지원 승낙":item.applicationStatus==="rejected"&&item.applicationOpen?"재지원":item.applicationStatus==="rejected"?"지원 반려":item.applicationOpen?"미션 지원":"모집 종료"}</button>`}</article>`}).join("");document.querySelector("#talent-mission-count")!.textContent=`승인 미션 ${items.length}개`;document.querySelector<HTMLElement>("#talent-mission-empty")!.hidden=items.length>0;list.querySelectorAll<HTMLButtonElement>("[data-talent-applicants]").forEach(button=>button.onclick=()=>openOwnerApplicants(Number(button.dataset.talentApplicants),button.dataset.title??"미션"));list.querySelectorAll<HTMLButtonElement>("[data-mission-apply]:not(:disabled):not([data-mission-cancel])").forEach(button=>button.onclick=()=>applyMission(Number(button.dataset.missionApply)));list.querySelectorAll<HTMLButtonElement>("[data-mission-cancel]").forEach(button=>button.onclick=()=>cancelMissionApplication(Number(button.dataset.missionCancel)));const rejected=items.find(item=>item.applicationStatus==="rejected"&&item.applicationDecidedAt&&localStorage.getItem(`paxlink.mission.application.rejected.${item.id}`)!==item.applicationDecidedAt);if(rejected){localStorage.setItem(`paxlink.mission.application.rejected.${rejected.id}`,String(rejected.applicationDecidedAt));modal("미션 지원 결과",`<strong>${escapeHtml(rejected.title)}</strong><p>지원이 반려되었습니다.</p><dl><dt>반려 사유</dt><dd>${escapeHtml(rejected.applicationRejectionReason??"반려 사유가 저장되지 않은 이전 처리 건입니다.")}</dd></dl>`)}}catch(error){console.error(error)}}
function markParticipatingMissions(){document.querySelectorAll<HTMLButtonElement>('.talent-mission-card [data-mission-apply].applied').forEach(button=>{if(button.textContent!=="지원 승낙")return;const card=button.closest<HTMLElement>(".talent-mission-card"),summary=card?.querySelector<HTMLElement>("header>b"),missionId=Number(button.dataset.missionApply),title=card?.querySelector("h3")?.textContent??"미션";if(summary&&!summary.querySelector(".participating-status")){summary.insertAdjacentHTML("beforeend",'<span class="participating-status">참여중</span>');const activity=document.createElement("button");activity.type="button";activity.className="mission-activity-open";activity.textContent="활동일지";activity.onclick=event=>{event.stopPropagation();void openMissionActivity(missionId,title)};summary.append(activity)}button.textContent="참여중";button.classList.add("participating")})}
new MutationObserver(markParticipatingMissions).observe(document.documentElement,{childList:true,subtree:true});
