document.head.insertAdjacentHTML("beforeend",'<style>.mission-activity-modal>.member-modal-box{display:flex;flex-direction:column}.mission-activity-modal>.member-modal-box>.mission-activity-body{flex:1;min-height:0}.mission-activity-modal>.member-modal-box>footer{flex:0 0 auto;align-items:center;justify-content:center;min-height:70px;margin:0;padding:14px 20px;border-top:1px solid var(--line);background:#fff}.mission-activity-modal>.member-modal-box>footer .green-outline{width:120px;min-width:120px;height:42px;margin:0;border-radius:9px;font-weight:700}.mission-activity-form.owner-view-only{display:none}.member-mission-owner-activity{margin:12px 0 0 6px;padding:6px 10px;border:1px solid #8fcfba;border-radius:12px;background:#fff;color:var(--green);font-size:9px;font-weight:700;cursor:pointer}@media(max-width:620px){.mission-activity-modal>.member-modal-box>footer{min-height:62px;padding:10px 14px}.mission-activity-modal>.member-modal-box>footer .green-outline{width:110px;min-width:110px;height:40px}}</style>');
async function openMissionActivity(missionId:number,title:string,viewOnly=false){document.querySelector(".mission-activity-modal")?.remove();const layer=document.createElement("div");layer.className="member-modal mission-activity-modal";layer.innerHTML=`<section class="member-modal-box"><h3>${escapeHtml(title)} 활동일지</h3><div class="mission-activity-body"><form class="mission-activity-form${viewOnly?" owner-view-only":""}"><h4>활동일지 등록</h4><div class="mission-activity-schedule"><label>활동일<input type="date" name="activityDate" required></label><label>시작시간<input type="time" name="timeFrom" required></label><span>~</span><label>종료시간<input type="time" name="timeTo" required></label></div><label>한 일<textarea name="content" maxlength="5000" rows="5" required placeholder="미션에서 한 일을 작성해 주세요."></textarea></label><footer><p></p><button class="green-button" type="submit" disabled>활동일지 등록</button></footer></form><section class="mission-activity-list"><header><h4>참여자 활동 내역</h4><span data-activity-count></span></header><div class="mission-activity-items">불러오는 중...</div></section></div><footer><button class="green-outline" type="button">닫기</button></footer></section>`;document.body.append(layer);layer.querySelector<HTMLElement>(":scope>.member-modal-box>footer button")!.onclick=()=>layer.remove();const form=layer.querySelector<HTMLFormElement>("form")!,date=form.querySelector<HTMLInputElement>('[name="activityDate"]')!,from=form.querySelector<HTMLInputElement>('[name="timeFrom"]')!,to=form.querySelector<HTMLInputElement>('[name="timeTo"]')!,content=form.querySelector<HTMLTextAreaElement>('[name="content"]')!,submit=form.querySelector<HTMLButtonElement>('button[type="submit"]')!,sync=()=>submit.disabled=!date.value||!from.value||!to.value||from.value>=to.value||!content.value.trim();form.addEventListener("input",sync);form.onsubmit=async event=>{event.preventDefault();if(viewOnly||submit.disabled)return;submit.disabled=true;const error=form.querySelector("p")!;error.textContent="";try{await catacombApi(`/api/parishioner/missions/${missionId}/activity-logs`,{method:"POST",body:JSON.stringify({activityDate:date.value,timeFrom:from.value,timeTo:to.value,content:content.value})});layer.remove();await openMissionActivity(missionId,title)}catch(reason){error.textContent=(reason as Error).message;sync()}};try{const items=await catacombApi<MissionActivity[]>(`/api/parishioner/missions/${missionId}/activity-logs`),itemsRoot=layer.querySelector(".mission-activity-items")!;layer.querySelector("[data-activity-count]")!.textContent=`총 ${items.length}건`;itemsRoot.innerHTML=items.length?items.map(item=>`<article class="mission-activity-log"><header><strong>${escapeHtml(item.authorName)}</strong><time>${item.activityDate} · ${item.timeFrom} ~ ${item.timeTo}</time></header><p>${escapeHtml(item.content)}</p><small>작성 ${new Date(item.createdAt).toLocaleString("ko-KR")}</small></article>`).join(""):'<p class="mission-activity-empty">등록된 활동일지가 없습니다.</p>'}catch(error){layer.querySelector(".mission-activity-items")!.textContent=(error as Error).message}}
function mountOwnerActivityButtons(){document.querySelectorAll<HTMLButtonElement>(".member-mission-applicants").forEach(applicants=>{const card=applicants.closest<HTMLElement>(".member-mission-card");if(!card||card.querySelector("[data-member-owner-activity]"))return;const button=document.createElement("button");button.type="button";button.className="member-mission-owner-activity";button.dataset.memberOwnerActivity=applicants.dataset.ownerApplicants;button.textContent="활동일지 확인";button.onclick=()=>openMissionActivity(Number(applicants.dataset.ownerApplicants),applicants.dataset.title??"미션",true);applicants.insertAdjacentElement("afterend",button)})}new MutationObserver(mountOwnerActivityButtons).observe(document.body,{childList:true,subtree:true});mountOwnerActivityButtons();
function applyMission(id:number){const layer=document.createElement("div");layer.className="member-modal mission-apply-modal";layer.innerHTML=`<section class="member-modal-box"><h3>미션 지원 요청</h3><form><label>등록자에게 전달할 메시지<textarea maxlength="2000" rows="7" required placeholder="지원 동기와 전달할 메시지를 작성해 주세요."></textarea></label><p></p><div><button class="green-outline" type="button">취소</button><button class="green-button" type="submit" disabled>지원 요청</button></div></form></section>`;document.body.append(layer);const textarea=layer.querySelector<HTMLTextAreaElement>("textarea")!,submit=layer.querySelector<HTMLButtonElement>('button[type="submit"]')!;textarea.addEventListener("input",()=>submit.disabled=!textarea.value.trim());layer.querySelector<HTMLButtonElement>('button[type="button"]')!.onclick=()=>layer.remove();layer.querySelector<HTMLFormElement>("form")!.onsubmit=async event=>{event.preventDefault();if(!textarea.value.trim())return;const error=layer.querySelector("form>p")!;submit.disabled=true;try{await catacombApi<{message:string}>(`/api/parishioner/missions/${id}/apply`,{method:"POST",body:JSON.stringify({message:textarea.value})});layer.remove();await loadTalentMissions();modal("지원하였습니다","<p>지원하였습니다.</p>")}catch(reason){error.textContent=(reason as Error).message;submit.disabled=!textarea.value.trim()}}}
async function cancelMissionApplication(id:number){try{const result=await catacombApi<{message:string}>(`/api/parishioner/missions/${id}/application`,{method:"DELETE"});await loadTalentMissions();modal("지원 취소",`<p>${escapeHtml(result.message)}</p>`)}catch(error){modal("지원 취소",`<p>${escapeHtml((error as Error).message)}</p>`)}}
async function openOwnerApplicants(id:number,title:string){const layer=document.createElement("div");layer.className="member-modal owner-applicants-modal";layer.innerHTML=`<section class="member-modal-box"><h3>${escapeHtml(title)} 지원자</h3><div class="member-modal-body owner-applicants-body">불러오는 중...</div><button class="green-outline" type="button">닫기</button></section>`;document.body.append(layer);layer.querySelector<HTMLButtonElement>(":scope>.member-modal-box>button")!.onclick=()=>layer.remove();try{const result=await catacombApi<{items:Array<{id:number;name:string;baptismalName:string|null;email:string;mobile:string;message:string;status:"requested"|"approved"|"rejected";rejectionReason:string|null;appliedAt:string;approvedAt:string|null}>}>(`/api/parishioner/missions/${id}/applicants`);const labels={requested:"결정 대기",approved:"승인",rejected:"반려"};layer.querySelector(".owner-applicants-body")!.innerHTML=result.items.length?`<div class="owner-applicants-grid"><table><thead><tr><th>이름</th><th>연락처</th><th>지원일</th><th>승인일</th><th>지원 메시지</th><th>상태</th><th>결정</th></tr></thead><tbody>${result.items.map(item=>`<tr><td><strong>${escapeHtml(item.name)}${item.baptismalName?` (${escapeHtml(item.baptismalName)})`:""}</strong></td><td>${escapeHtml(item.email)}<br>${escapeHtml(item.mobile??"-")}</td><td class="owner-applicant-date">${escapeHtml(item.appliedAt)}</td><td class="owner-applicant-date">${escapeHtml(item.approvedAt??"-")}</td><td class="owner-applicant-message">${escapeHtml(item.message)}${item.rejectionReason?`<div class="owner-application-reason"><strong>반려 사유</strong><p>${escapeHtml(item.rejectionReason)}</p></div>`:""}</td><td><b class="owner-applicant-status ${item.status}">${labels[item.status]}</b></td><td>${item.status==="requested"?`<div class="owner-applicant-decisions"><button data-owner-decision="rejected" data-id="${item.id}" type="button">반려</button><button data-owner-decision="approved" data-id="${item.id}" type="button">승인</button></div>`:"-"}</td></tr>`).join("")}</tbody></table></div>`:'<p>지원자가 없습니다.</p>';layer.querySelectorAll<HTMLButtonElement>("[data-owner-decision]").forEach(button=>button.onclick=async()=>{const status=button.dataset.ownerDecision,rejectionReason=status==="rejected"?await promptApplicationRejection():"";if(status==="rejected"&&rejectionReason===null)return;await catacombApi(`/api/parishioner/mission-applications/${button.dataset.id}/decision`,{method:"PATCH",body:JSON.stringify({status,rejectionReason})});layer.remove();await Promise.all([loadMyMissions(),loadTalentMissions()])})}catch(error){layer.querySelector(".owner-applicants-body")!.textContent=(error as Error).message}}
new MutationObserver(()=>{document.querySelectorAll<HTMLButtonElement>(".member-mission-applicants").forEach(applicants=>{const card=applicants.closest<HTMLElement>(".member-mission-card");if(!card||card.querySelector("[data-owner-questions]"))return;const button=document.createElement("button"),missionId=Number(applicants.dataset.ownerApplicants);button.type="button";button.className="member-mission-questions";button.dataset.ownerQuestions=String(missionId);button.textContent="답변/질문 : 0 / 0";button.onclick=()=>openOwnerQuestions(missionId,applicants.dataset.title??"미션");applicants.insertAdjacentElement("afterend",button);void catacombApi<{questions:Array<{answer:string|null}>}>(`/api/parishioner/missions/${missionId}/community`).then(data=>button.textContent=`답변/질문 : ${data.questions.filter(question=>Boolean(question.answer)).length} / ${data.questions.length}`).catch(()=>{button.textContent="답변/질문 확인"})})}).observe(document.body,{childList:true,subtree:true});
async function openOwnerQuestions(missionId:number,title:string){const layer=document.createElement("div");layer.className="member-modal owner-questions-modal";layer.innerHTML=`<section class="member-modal-box"><h3>${escapeHtml(title)} 질문·답변</h3><div class="member-modal-body owner-questions-body">불러오는 중...</div><button class="green-outline" type="button">닫기</button></section>`;document.body.append(layer);layer.querySelector<HTMLButtonElement>(":scope>.member-modal-box>button")!.onclick=()=>layer.remove();try{const data=await catacombApi<{isOwner:boolean;questions:Array<{id:number;question:string;answer:string|null;askerName:string;createdAt:string}>}>(`/api/parishioner/missions/${missionId}/community`),root=layer.querySelector(".owner-questions-body")!;root.innerHTML=data.questions.length?data.questions.map(question=>`<article class="owner-question"><header><strong>${escapeHtml(question.askerName)}</strong><time>${new Date(question.createdAt).toLocaleString("ko-KR")}</time></header><p>${escapeHtml(question.question)}</p>${question.answer?`<div class="owner-answer"><b>내 답변</b><p>${escapeHtml(question.answer)}</p></div>`:data.isOwner?`<form data-owner-answer="${question.id}"><textarea maxlength="5000" rows="5" required placeholder="질문에 대한 답변을 입력해 주세요."></textarea><button class="green-button" type="submit">답변 등록</button></form>`:'<small>답변 권한이 없습니다.</small>'}</article>`).join(""):'<p class="owner-question-empty">등록된 질문이 없습니다.</p>';root.querySelectorAll<HTMLFormElement>("[data-owner-answer]").forEach(form=>form.onsubmit=async event=>{event.preventDefault();await catacombApi(`/api/parishioner/mission-questions/${form.dataset.ownerAnswer}/answer`,{method:"PATCH",body:JSON.stringify({answer:form.querySelector("textarea")!.value})});layer.remove();await loadMyMissions()})}catch(error){layer.querySelector(".owner-questions-body")!.textContent=(error as Error).message}}
const missionCommunityLabels={like:"👍 좋아요",best:"🌟 최고예요",cheer:"💪 힘내요",funny:"😂 웃겨요",cool:"😎 멋져요",sad:"😢 슬퍼요",regret:"😔 아쉬워요"};
new MutationObserver(()=>{document.querySelectorAll<HTMLElement>(".talent-mission-card").forEach(card=>{if(card.dataset.communityReady)return;const apply=card.querySelector<HTMLButtonElement>("[data-mission-apply]");if(!apply)return;card.dataset.communityReady="true";const root=document.createElement("section");root.className="mission-community";root.dataset.missionId=apply.dataset.missionApply;apply.insertAdjacentElement("beforebegin",root);void loadMissionCommunity(Number(apply.dataset.missionApply),root)})}).observe(document.body,{childList:true,subtree:true});
async function loadMissionCommunity(missionId:number,root:HTMLElement){try{const data=await catacombApi<{isOwner:boolean;reactions:Array<{reaction:string;count:number;mine:boolean}>;questions:Array<{id:number;question:string;answer:string|null;askerName:string;createdAt:string;reactions:Array<{target:"question"|"answer";reaction:string;count:number;mine:boolean}>}>}>(`/api/parishioner/missions/${missionId}/community`),counts=(target:Array<{reaction:string;count:number;mine:boolean}>,key:string)=>target.find(item=>item.reaction===key);root.innerHTML=`<div class="mission-main-reactions">${(["like","best","cheer","funny","cool"] as const).map(key=>{const item=counts(data.reactions,key);return`<button class="${item?.mine?"selected":""}" data-mission-community-reaction="${key}" type="button">${missionCommunityLabels[key]} <b>${item?.count??0}</b></button>`}).join("")}</div><div class="mission-qa"><header><strong>질문과 답변</strong><span>${data.questions.length}개</span></header><div class="mission-question-list">${data.questions.map(question=>`<article class="mission-question"><header><strong>${escapeHtml(question.askerName)}</strong><time>${new Date(question.createdAt).toLocaleString("ko-KR")}</time></header><p>${escapeHtml(question.question)}</p>${reactionButtons(question.id,"question",question.reactions)}${question.answer?`<div class="mission-answer"><b>등록자 답변</b><p>${escapeHtml(question.answer)}</p>${reactionButtons(question.id,"answer",question.reactions)}</div>`:data.isOwner?`<form data-mission-answer="${question.id}"><textarea maxlength="5000" required placeholder="등록자 답변을 입력해 주세요."></textarea><button type="submit">답변 등록</button></form>`:'<small class="answer-waiting">등록자의 답변을 기다리고 있습니다.</small>'}</article>`).join("")}</div><form class="mission-question-form"><input class="mission-question-input" maxlength="2000" required placeholder="미션에 대해 질문해 주세요"><button type="submit">질문 등록</button></form></div>`;root.querySelectorAll<HTMLButtonElement>("[data-mission-community-reaction]").forEach(button=>button.onclick=async()=>{await catacombApi(`/api/parishioner/missions/${missionId}/reaction`,{method:"PUT",body:JSON.stringify({reaction:button.dataset.missionCommunityReaction})});await loadMissionCommunity(missionId,root)});root.querySelectorAll<HTMLButtonElement>("[data-qa-reaction]").forEach(button=>button.onclick=async()=>{await catacombApi(`/api/parishioner/mission-questions/${button.dataset.question}/reaction`,{method:"PUT",body:JSON.stringify({target:button.dataset.target,reaction:button.dataset.qaReaction})});await loadMissionCommunity(missionId,root)});root.querySelector<HTMLFormElement>(".mission-question-form")!.onsubmit=async event=>{event.preventDefault();const input=(event.currentTarget as HTMLFormElement).querySelector<HTMLInputElement>(".mission-question-input")!;await catacombApi(`/api/parishioner/missions/${missionId}/questions`,{method:"POST",body:JSON.stringify({question:input.value})});await loadMissionCommunity(missionId,root)};root.querySelectorAll<HTMLFormElement>("[data-mission-answer]").forEach(form=>form.onsubmit=async event=>{event.preventDefault();await catacombApi(`/api/parishioner/mission-questions/${form.dataset.missionAnswer}/answer`,{method:"PATCH",body:JSON.stringify({answer:form.querySelector("textarea")!.value})});await loadMissionCommunity(missionId,root)})}catch(error){root.innerHTML=`<p class="community-error">${escapeHtml((error as Error).message)}</p>`}}
function reactionButtons(questionId:number,target:"question"|"answer",items:Array<{target:string;reaction:string;count:number;mine:boolean}>){return`<div class="mission-qa-reactions">${(Object.keys(missionCommunityLabels) as Array<keyof typeof missionCommunityLabels>).map(key=>{const item=items.find(value=>value.target===target&&value.reaction===key);return`<button class="${item?.mine?"selected":""}" data-qa-reaction="${key}" data-question="${questionId}" data-target="${target}" type="button">${missionCommunityLabels[key]} <b>${item?.count??0}</b></button>`}).join("")}</div>`}
