function openQuestionEdit(missionId:number,questionId:number,question:string,anonymous:boolean,root:HTMLElement){const layer=document.createElement("div");layer.className="member-modal question-edit-modal";layer.innerHTML=`<section class="member-modal-box"><h3>질문 수정</h3><form><label><textarea aria-label="질문" maxlength="2000" rows="7" required>${escapeHtml(question)}</textarea></label><label class="question-edit-anonymous"><input type="checkbox" ${anonymous?"checked":""}> 익명으로 질문</label><p></p><div><button class="green-outline" type="button">취소</button><button class="green-button" type="submit" disabled>수정 저장</button></div></form></section>`;document.body.append(layer);const textarea=layer.querySelector<HTMLTextAreaElement>("textarea")!,submit=layer.querySelector<HTMLButtonElement>('button[type="submit"]')!;const syncSubmit=()=>submit.disabled=!textarea.value.trim();textarea.addEventListener("input",syncSubmit);syncSubmit();layer.querySelector<HTMLButtonElement>('button[type="button"]')!.onclick=()=>layer.remove();layer.querySelector<HTMLFormElement>("form")!.onsubmit=async event=>{event.preventDefault();if(!textarea.value.trim())return;const error=layer.querySelector("form>p")!;submit.disabled=true;try{await catacombApi(`/api/parishioner/mission-questions/${questionId}`,{method:"PATCH",body:JSON.stringify({question:textarea.value,anonymous:layer.querySelector<HTMLInputElement>('.question-edit-anonymous input')!.checked})});layer.remove();await loadMissionCommunity(missionId,root)}catch(reason){error.textContent=(reason as Error).message;syncSubmit()}}}
