async function openShrinePhotos(shrineId:number,shrineName:string){document.querySelector(".shrine-photo-modal")?.remove();const layer=document.createElement("div");layer.className="member-modal shrine-photo-modal";layer.innerHTML=`<section class="member-modal-box"><h3>${escapeHtml(shrineName)} 방문 사진</h3><div class="shrine-photo-modal-body"><form><label>사진 제목<input name="title" maxlength="200" required placeholder="사진 제목을 입력해 주세요"></label><label>태그<input name="tags" maxlength="1000" placeholder="쉼표(,) 또는 띄어쓰기로 구분"></label><div class="shrine-photo-tag-preview" hidden></div><label>사진 선택<input name="photo" type="file" accept="image/jpeg,image/png,image/webp,image/gif" required></label><p></p><button class="green-button" type="submit" disabled>사진 등록</button></form><section><header><h4>등록한 사진</h4><span></span></header><div class="shrine-photo-list">불러오는 중...</div></section></div><footer><button class="green-outline" type="button">닫기</button></footer></section>`;document.body.append(layer);layer.querySelector<HTMLButtonElement>(":scope>.member-modal-box>footer button")!.onclick=()=>layer.remove();const form=layer.querySelector<HTMLFormElement>("form")!,title=form.querySelector<HTMLInputElement>('[name="title"]')!,tags=form.querySelector<HTMLInputElement>('[name="tags"]')!,file=form.querySelector<HTMLInputElement>('[name="photo"]')!,submit=form.querySelector<HTMLButtonElement>('button[type="submit"]')!,preview=form.querySelector<HTMLElement>(".shrine-photo-tag-preview")!,sync=()=>{const parsed=[...new Set(tags.value.split(/[,\s]+/).map(tag=>tag.replace(/^#/,"").trim()).filter(Boolean))];preview.innerHTML=parsed.map(tag=>`<span>#${escapeHtml(tag)}</span>`).join("");preview.hidden=!parsed.length;submit.disabled=!title.value.trim()||!file.files?.[0]};form.oninput=sync;form.onsubmit=async event=>{event.preventDefault();const selected=file.files?.[0];if(!selected||submit.disabled)return;if(selected.size>5*1024*1024){form.querySelector("p")!.textContent="사진은 5MB 이하로 등록해 주세요.";return}submit.disabled=true;try{const imageData=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error("사진을 읽지 못했습니다."));reader.readAsDataURL(selected)});await catacombApi(`/api/parishioner/shrines/${shrineId}/photos`,{method:"POST",body:JSON.stringify({title:title.value,tags:tags.value,imageType:selected.type,imageData})});layer.remove();await loadMemberShrines();await openShrinePhotos(shrineId,shrineName)}catch(error){form.querySelector("p")!.textContent=(error as Error).message;sync()}};try{const photos=await catacombApi<ShrinePhoto[]>(`/api/parishioner/shrines/${shrineId}/photos`),list=layer.querySelector(".shrine-photo-list")!;layer.querySelector(".shrine-photo-modal-body>section header span")!.textContent=`총 ${photos.length}장`;list.innerHTML=photos.length?photos.map(photo=>`<article><img src="${photo.imageUrl}" alt="${escapeHtml(photo.title)}"><div><h5>${escapeHtml(photo.title)}</h5>${photo.tags.length?`<div>${photo.tags.map(tag=>`<span>#${escapeHtml(tag)}</span>`).join("")}</div>`:""}<time>${new Date(photo.createdAt).toLocaleString("ko-KR")}</time></div></article>`).join(""):'<p class="member-shrine-empty">등록한 방문 사진이 없습니다.</p>'}catch(error){layer.querySelector(".shrine-photo-list")!.textContent=(error as Error).message}}
function enhanceShrineReviews(){document.querySelectorAll<HTMLButtonElement>("[data-shrine-photo]").forEach(button=>{button.childNodes[0]!.textContent="순례후기 등록 ";});const layer=document.querySelector<HTMLElement>(".shrine-photo-modal");if(!layer||layer.dataset.reviewReady)return;layer.dataset.reviewReady="true";const form=layer.querySelector<HTMLFormElement>("form")!,title=form.querySelector<HTMLInputElement>('[name="title"]')!,tags=form.querySelector<HTMLInputElement>('[name="tags"]')!,file=form.querySelector<HTMLInputElement>('[name="photo"]')!,submit=form.querySelector<HTMLButtonElement>('button[type="submit"]')!,error=form.querySelector<HTMLElement>("p")!;title.closest("label")!.childNodes[0]!.textContent="후기 제목";title.placeholder="순례후기 제목을 입력해 주세요";title.closest("label")!.insertAdjacentHTML("afterend",'<label class="shrine-review-text">순례 후기<textarea name="reviewText" maxlength="10000" rows="6" required placeholder="성지를 순례하며 느낀 점과 이야기를 작성해 주세요."></textarea></label>');const originalFileLabel=file.closest("label")!;originalFileLabel.className="shrine-review-photos";originalFileLabel.innerHTML='<span>사진</span><div class="shrine-photo-dropzone" tabindex="0" role="button" aria-label="사진을 선택하거나 이곳에 끌어다 놓으세요"><strong>사진을 끌어다 놓으세요</strong><small>또는 아래 추가 버튼으로 선택 · JPG, PNG, WEBP, GIF (장당 5MB)</small></div><div class="shrine-photo-queue"></div><button class="green-outline shrine-photo-add" type="button">+ 추가</button><input name="photo" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple hidden>';const picker=originalFileLabel.querySelector<HTMLInputElement>('[name="photo"]')!,dropzone=originalFileLabel.querySelector<HTMLElement>(".shrine-photo-dropzone")!,queue=originalFileLabel.querySelector<HTMLElement>(".shrine-photo-queue")!,add=originalFileLabel.querySelector<HTMLButtonElement>(".shrine-photo-add")!,review=form.querySelector<HTMLTextAreaElement>('[name="reviewText"]')!,files:File[]=[];layer.querySelector("h3")!.textContent=layer.querySelector("h3")!.textContent!.replace("방문 사진","순례후기");layer.querySelector("h4")!.textContent="등록한 순례후기";submit.textContent="순례후기 등록";const sync=()=>submit.disabled=!title.value.trim()||!review.value.trim()||!files.length;const renderFiles=()=>{queue.innerHTML=files.map((item,index)=>`<article><img src="${URL.createObjectURL(item)}" alt=""><span><b>${escapeHtml(item.name)}</b><small>${(item.size/1024/1024).toFixed(2)} MB</small></span><button type="button" data-remove-photo="${index}" aria-label="${escapeHtml(item.name)} 삭제">×</button></article>`).join("");sync()};const addFiles=(incoming:FileList|File[])=>{error.textContent="";for(const item of Array.from(incoming)){if(!/^image\/(jpeg|png|webp|gif)$/i.test(item.type)){error.textContent="JPG, PNG, WEBP 또는 GIF 사진만 추가할 수 있습니다.";continue}if(item.size>5*1024*1024){error.textContent=`${item.name}: 사진은 장당 5MB 이하로 등록해 주세요.`;continue}files.push(item)}picker.value="";renderFiles()};add.onclick=()=>picker.click();dropzone.onclick=()=>picker.click();dropzone.onkeydown=event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();picker.click()}};picker.onchange=()=>{if(picker.files)addFiles(picker.files)};["dragenter","dragover"].forEach(name=>dropzone.addEventListener(name,event=>{event.preventDefault();dropzone.classList.add("is-dragging")}));["dragleave","drop"].forEach(name=>dropzone.addEventListener(name,event=>{event.preventDefault();dropzone.classList.remove("is-dragging")}));dropzone.addEventListener("drop",event=>{if(event.dataTransfer?.files)addFiles(event.dataTransfer.files)});queue.onclick=event=>{const button=(event.target as HTMLElement).closest<HTMLButtonElement>("[data-remove-photo]");if(!button)return;files.splice(Number(button.dataset.removePhoto),1);renderFiles()};form.addEventListener("input",sync);form.addEventListener("submit",async event=>{event.preventDefault();event.stopImmediatePropagation();if(submit.disabled)return;submit.disabled=true;error.textContent=`사진 ${files.length}장을 등록하는 중입니다.`;try{const shrineId=Number(document.querySelector<HTMLButtonElement>("[data-shrine-photo]._review-active")?.dataset.shrinePhoto??layer.dataset.shrineId);for(let index=0;index<files.length;index++){const selected=files[index]!,imageData=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error("사진을 읽지 못했습니다."));reader.readAsDataURL(selected)});error.textContent=`사진 ${index+1}/${files.length}장을 등록하는 중입니다.`;await catacombApi(`/api/parishioner/shrines/${shrineId}/photos`,{method:"POST",body:JSON.stringify({title:title.value,reviewText:review.value,tags:tags.value,imageType:selected.type,imageData})})}layer.remove();await loadMemberShrines();modal("순례후기",`<p>순례후기와 사진 ${files.length}장을 등록했습니다.</p>`)}catch(reason){error.textContent=(reason as Error).message;sync()}},true);const heading=layer.querySelector("h3")!.textContent??"",shrine=memberShrines.find(item=>heading.startsWith(item.name));if(shrine){layer.dataset.shrineId=String(shrine.id);void catacombApi<ShrinePhoto[]>(`/api/parishioner/shrines/${shrine.id}/photos`).then(photos=>{const list=layer.querySelector<HTMLElement>(".shrine-photo-list")!,decorate=()=>{[...list.querySelectorAll<HTMLElement>(":scope>article")].forEach((article,index)=>{if(article.querySelector(".shrine-review-copy"))return;const text=photos[index]?.reviewText;if(text)article.querySelector(":scope>div")?.insertAdjacentHTML("beforeend",`<p class="shrine-review-copy">${escapeHtml(text)}</p>`)})};new MutationObserver(decorate).observe(list,{childList:true});decorate()})}}
