function applyMeetingTerminology(root:Node=document.body){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node:Node|null;while(node=walker.nextNode()){const parent=node.parentElement;if(!parent||parent.matches("script,style"))continue;if(node.textContent?.includes("단체"))node.textContent=node.textContent.replaceAll("단체","모임")}}
new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>applyMeetingTerminology(node)))).observe(document.body,{childList:true,subtree:true});
applyMeetingTerminology();
function applyMoreLabels(root:ParentNode=document){root.querySelectorAll<HTMLButtonElement>("button").forEach(button=>{if(button.textContent?.trim().toLowerCase()==="more")button.textContent="더보기"})}
new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node instanceof Element)applyMoreLabels(node)}))).observe(document.body,{childList:true,subtree:true});
