const memberFontScaleKey="paxlink.parishioner.font-scale";
function readMemberFontScale(){const value=Number(localStorage.getItem(memberFontScaleKey)??100);return Number.isFinite(value)?Math.min(140,Math.max(80,Math.round(value/10)*10)):100}
let memberFontScale=readMemberFontScale();
function applyMemberFontScale(value=memberFontScale){memberFontScale=Math.min(140,Math.max(80,value));document.body.style.zoom=String(memberFontScale/100);localStorage.setItem(memberFontScaleKey,String(memberFontScale));document.querySelectorAll<HTMLElement>("[data-member-font-value]").forEach(element=>element.textContent=`${memberFontScale}%`);document.querySelectorAll<HTMLButtonElement>("[data-member-font-action]").forEach(button=>{button.disabled=button.dataset.memberFontAction==="decrease"?memberFontScale<=80:button.dataset.memberFontAction==="increase"?memberFontScale>=140:false})}
function openMemberPreferences(){document.querySelector(".member-preferences-modal")?.remove();const layer=document.createElement("div");layer.className="member-modal member-preferences-modal";layer.innerHTML='<section class="member-modal-box"><h3>환경설정</h3><div class="member-modal-body"><section class="member-font-setting"><div><strong>글자 크기</strong><p>화면의 글자와 콘텐츠 크기를 조절합니다.</p></div><div class="member-font-controls"><button class="green-outline" data-member-font-action="decrease" type="button" aria-label="글자 크기 축소">A−</button><b data-member-font-value></b><button class="green-outline" data-member-font-action="increase" type="button" aria-label="글자 크기 확대">A＋</button></div><div class="member-font-sample"><small>미리보기</small><p>성당 공동체의 소식을 편안한 크기로 확인하세요.</p></div><button class="member-font-reset green-outline" data-member-font-action="reset" type="button">기본 크기로 복원</button></section></div><footer><button class="green-button" type="button">확인</button></footer></section>';document.body.append(layer);layer.querySelector<HTMLButtonElement>('[data-member-font-action="decrease"]')!.onclick=()=>applyMemberFontScale(memberFontScale-10);layer.querySelector<HTMLButtonElement>('[data-member-font-action="increase"]')!.onclick=()=>applyMemberFontScale(memberFontScale+10);layer.querySelector<HTMLButtonElement>('[data-member-font-action="reset"]')!.onclick=()=>applyMemberFontScale(100);layer.querySelector<HTMLButtonElement>(":scope>.member-modal-box>footer button")!.onclick=()=>layer.remove();applyMemberFontScale()}
function mountMemberPreferences(){const footer=document.querySelector<HTMLElement>("#member-mobile-menu>footer"),privacy=footer?.querySelector<HTMLButtonElement>("#member-privacy");if(!footer||!privacy||footer.querySelector("#member-preferences"))return;const button=document.createElement("button");button.id="member-preferences";button.type="button";button.textContent="환경설정";button.onclick=()=>{document.body.classList.remove("member-menu-open");document.querySelector("#member-mobile-menu")?.classList.remove("open");document.querySelector<HTMLElement>("#member-menu-backdrop")!.hidden=true;openMemberPreferences()};privacy.insertAdjacentElement("afterend",button)}

type MemberParishInformation={basic:{name:string;diocese:string|null;district:string|null;jurisdiction:string|null;postalCode:string|null;address:string|null;addressDetail:string|null;phone:string|null;officePhone:string|null;fax:string|null;homepage:string|null};history:Array<{year:number;month:number;title:string;description:string|null}>;priests:Array<{name:string;baptismalName:string|null;role:string|null;appointmentDate:string|null;affiliation:string|null;generation:number|null}>};
let memberParishInformation:MemberParishInformation|null=null;
async function openMemberParishInformation(kind:"basic"|"history"|"contact"|"priests"){document.querySelector(".member-parish-information-modal")?.remove();const labels={basic:"기본정보",history:"연혁",contact:"성당연락처",priests:"신부"},layer=document.createElement("div");layer.className=`member-modal member-parish-information-modal${kind==="priests"?" member-parish-priest-modal":""}`;layer.innerHTML=`<section class="member-modal-box"><h3>성당정보 · ${labels[kind]}</h3><div class="member-modal-body"><p class="member-parish-information-loading">성당 정보를 불러오는 중입니다.</p></div><footer><button class="green-outline" type="button">닫기</button></footer></section>`;document.body.append(layer);layer.querySelector<HTMLButtonElement>("footer button")!.onclick=()=>layer.remove();try{if(!memberParishInformation){const response=await fetch("/api/parishioner/parish-information"),data=await response.json() as MemberParishInformation&{message?:string};if(!response.ok)throw new Error(data.message??"성당 정보를 불러오지 못했습니다.");memberParishInformation=data}const data=memberParishInformation,b=data.basic,empty='<p class="member-parish-information-empty">등록된 정보가 없습니다.</p>';let html="";if(kind==="basic")html=`<dl><dt>성당명</dt><dd>${escapeHtml(b.name)}</dd><dt>교구</dt><dd>${escapeHtml(b.diocese??"-")}</dd><dt>지구</dt><dd>${escapeHtml(b.district??"-")}</dd><dt>관할</dt><dd>${escapeHtml(b.jurisdiction??"-")}</dd><dt>주소</dt><dd>${escapeHtml([b.postalCode,b.address,b.addressDetail].filter(Boolean).join(" ")||"-")}</dd>${b.homepage?`<dt>홈페이지</dt><dd><a href="${escapeHtml(b.homepage)}" target="_blank" rel="noopener">${escapeHtml(b.homepage)}</a></dd>`:""}</dl>`;else if(kind==="contact")html=`<dl><dt>대표전화</dt><dd>${escapeHtml(b.phone??"-")}</dd><dt>사무실</dt><dd>${escapeHtml(b.officePhone??"-")}</dd><dt>팩스</dt><dd>${escapeHtml(b.fax??"-")}</dd><dt>주소</dt><dd>${escapeHtml([b.postalCode,b.address,b.addressDetail].filter(Boolean).join(" ")||"-")}</dd></dl>`;else if(kind==="history")html=data.history.length?`<ol class="member-parish-history">${data.history.map(item=>`<li><time>${item.year}.${String(item.month).padStart(2,"0")}</time><div><strong>${escapeHtml(item.title)}</strong>${item.description?`<p>${escapeHtml(item.description)}</p>`:""}</div></li>`).join("")}</ol>`:empty;else html=data.priests.length?`<div class="member-parish-priests">${data.priests.map(item=>`<article><h4>${escapeHtml(item.name)}${item.baptismalName?` (${escapeHtml(item.baptismalName)})`:""}</h4><b>${escapeHtml(item.role??"신부")}</b>${item.affiliation?`<p>${escapeHtml(item.affiliation)}</p>`:""}</article>`).join("")}</div>`:empty;layer.querySelector<HTMLElement>(".member-modal-body")!.innerHTML=html}catch(error){layer.querySelector<HTMLElement>(".member-modal-body")!.innerHTML=`<p class="member-parish-information-empty">${escapeHtml((error as Error).message)}</p>`}}
function mountMemberParishInformationMenu(){const nav=document.querySelector<HTMLElement>("#member-mobile-menu>nav"),notice=nav?.querySelector<HTMLButtonElement>('[data-member-target=".member-notices"]');if(!nav||!notice||nav.querySelector(".member-parish-information-menu"))return;const wrapper=document.createElement("div");wrapper.className="member-parish-information-menu";wrapper.innerHTML='<button class="member-parish-information-toggle" type="button" aria-expanded="false">성당정보 <span>⌄</span></button><div class="member-parish-information-submenu" hidden><button type="button" data-parish-information="basic">기본정보</button><button type="button" data-parish-information="history">연혁</button><button type="button" data-parish-information="contact">성당연락처</button><button type="button" data-parish-information="priests">신부</button></div>';notice.insertAdjacentElement("afterend",wrapper);const toggle=wrapper.querySelector<HTMLButtonElement>(".member-parish-information-toggle")!,submenu=wrapper.querySelector<HTMLElement>(".member-parish-information-submenu")!;toggle.onclick=()=>{const open=submenu.hidden;submenu.hidden=!open;toggle.setAttribute("aria-expanded",String(open))};wrapper.querySelectorAll<HTMLButtonElement>("[data-parish-information]").forEach(button=>button.onclick=()=>{document.body.classList.remove("member-menu-open");document.querySelector("#member-mobile-menu")?.classList.remove("open");document.querySelector<HTMLElement>("#member-menu-backdrop")!.hidden=true;void openMemberParishInformation(button.dataset.parishInformation as "basic"|"history"|"contact"|"priests")})}
